package com.pulsefit.authservice.service;
import io.jsonwebtoken.Jwts; import io.jsonwebtoken.security.Keys; import org.springframework.stereotype.Service; import javax.crypto.SecretKey; import java.nio.charset.StandardCharsets; import java.util.Date;
@Service public class JwtService { public static final String SECRET="PulseFit-College-Demo-Secret-Key-2026-ChangeMe-At-Least-32"; private SecretKey key(){return Keys.hmacShaKeyFor(SECRET.getBytes(StandardCharsets.UTF_8));} public String generate(String username,String role){long now=System.currentTimeMillis(); return Jwts.builder().subject(username).claim("role",role).issuedAt(new Date(now)).expiration(new Date(now+8*60*60*1000)).signWith(key()).compact();} public boolean valid(String token){try{Jwts.parser().verifyWith(key()).build().parseSignedClaims(token);return true;}catch(Exception e){return false;}}}
